-- case 1: [A01] a reading at the maximum datetime2 (9999-12-31) updates every existing row for its sensor
--[@tSQLt:NoTransaction](DEFAULT)
CREATE PROCEDURE [AgreedTests].[test 01 [A01 a reading at the maximum datetime2 (9999-12-31) updates every existing row for its sensor]
AS
BEGIN
  DELETE FROM [Warehouse].[ColdRoomTemperatures];
  INSERT INTO [Warehouse].[ColdRoomTemperatures] ([ColdRoomSensorNumber], [RecordedWhen], [Temperature]) VALUES
    (1, CAST('2020-01-01T00:00:00.000000' AS datetime2(7)), 1.00),
    (1, CAST('2020-01-01T00:00:00.000000' AS datetime2(7)), 2.00);
  SELECT TOP (0) [ColdRoomSensorNumber], [RecordedWhen], [Temperature] INTO #ExpectedState1 FROM [Warehouse].[ColdRoomTemperatures];
  INSERT INTO #ExpectedState1 ([ColdRoomSensorNumber], [RecordedWhen], [Temperature]) VALUES
    (1, CAST('9999-12-31T23:59:59.999999' AS datetime2(7)), 5.25),
    (1, CAST('9999-12-31T23:59:59.999999' AS datetime2(7)), 5.25);
  DECLARE @outcome nvarchar(4000) = N'completed';
  BEGIN TRY
    DECLARE @tvp0 [Website].[SensorDataList];
  INSERT INTO @tvp0 ([ColdRoomSensorNumber], [RecordedWhen], [Temperature]) VALUES (1, CAST('9999-12-31T23:59:59.999999' AS datetime2(7)), 5.25);
  EXEC Website.RecordColdRoomTemperatures @SensorReadings = @tvp0;
  END TRY
  BEGIN CATCH
    SET @outcome = CASE WHEN ERROR_NUMBER() IN (51000) THEN N'raised' ELSE N'unexpected error ' + CAST(ERROR_NUMBER() AS nvarchar(20)) + N': ' + ERROR_MESSAGE() END;
    -- a procedure that fails inside its own transaction can leave it open (and uncommittable); the test is outside
    -- tSQLt's transaction (NoTransaction), so this undoes only the procedure's work, as SQL Server does at batch end
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
  END CATCH;
  SELECT [ColdRoomSensorNumber], [RecordedWhen], [Temperature] INTO #ActualState1 FROM [Warehouse].[ColdRoomTemperatures];
  EXEC tSQLt.AssertEqualsString @Expected = N'completed', @Actual = @outcome, @Message = N'outcome';
  EXEC tSQLt.AssertEqualsTable @Expected = N'#ExpectedState1', @Actual = N'#ActualState1', @Message = N'Warehouse.ColdRoomTemperatures after the call';
END;
GO
